-- FO-10 part 1 (P-574 (3); AG-2-13a, -13b, -13d): the firm's assignment rules for new leads, one table in the front
-- office's area file (front-office-sales.prisma). Additive only: a new enum and a new table; no existing row changes.
-- Generated by `prisma migrate diff` against main's migrations, then the rules Prisma cannot say, below.

-- CreateEnum
CREATE TYPE "FoAssignStrategy" AS ENUM ('OWNER', 'ROUND_ROBIN');

-- CreateTable
CREATE TABLE "fo_assignment_rule" (
    "id" UUID NOT NULL DEFAULT gen_random_uuid(),
    "firm_id" UUID NOT NULL,
    "door" "FoDoor",
    "service_id" UUID,
    "criteria_key" TEXT NOT NULL,
    "strategy" "FoAssignStrategy" NOT NULL,
    "owner_staff_id" UUID,
    "eligible_staff_ids" UUID[] DEFAULT ARRAY[]::UUID[],
    "last_staff_id" UUID,
    "active" BOOLEAN NOT NULL DEFAULT true,
    "created_by" TEXT NOT NULL,
    "created_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updated_by" TEXT NOT NULL,
    "updated_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT "fo_assignment_rule_pkey" PRIMARY KEY ("id")
);

-- CreateIndex
CREATE UNIQUE INDEX "fo_assignment_rule_firm_id_criteria_key_key" ON "fo_assignment_rule"("firm_id", "criteria_key");

-- CreateIndex
CREATE UNIQUE INDEX "fo_assignment_rule_firm_id_id_key" ON "fo_assignment_rule"("firm_id", "id");

-- AddForeignKey
ALTER TABLE "fo_assignment_rule" ADD CONSTRAINT "fo_assignment_rule_firm_id_fkey" FOREIGN KEY ("firm_id") REFERENCES "fo_sales_setup"("firm_id") ON DELETE RESTRICT ON UPDATE RESTRICT;

-- AddForeignKey
ALTER TABLE "fo_assignment_rule" ADD CONSTRAINT "fo_assignment_rule_firm_id_service_id_fkey" FOREIGN KEY ("firm_id", "service_id") REFERENCES "fo_service"("firm_id", "id") ON DELETE RESTRICT ON UPDATE RESTRICT;


-- =====================================================================================================================
-- Rules Prisma cannot say (FO-10).
-- =====================================================================================================================

-- The criteria key is the criteria (one rule per door and service, any = ANY), so two rules can never claim the same
-- leads; a rule for leads added by hand is refused (the adder owns a lead they add, AG-2-4 rule 8, so it could never apply).
ALTER TABLE "fo_assignment_rule" ADD CONSTRAINT "fo_assignment_rule_criteria_check" CHECK (
  "criteria_key" = coalesce("door"::text, 'ANY') || ':' || coalesce("service_id"::text, 'ANY')
  AND "door" IS DISTINCT FROM 'MANUAL');
-- OWNER names exactly one person and no eligible set; ROUND_ROBIN names no owner (AG-2-13b: strategy and eligible set).
ALTER TABLE "fo_assignment_rule" ADD CONSTRAINT "fo_assignment_rule_strategy_check" CHECK (
  "eligible_staff_ids" IS NOT NULL
  AND CASE "strategy"
    WHEN 'OWNER' THEN "owner_staff_id" IS NOT NULL AND cardinality("eligible_staff_ids") = 0
    WHEN 'ROUND_ROBIN' THEN "owner_staff_id" IS NULL
  END);
ALTER TABLE "fo_assignment_rule" ADD CONSTRAINT "fo_assignment_rule_by_check" CHECK (fo_sales_has_word("created_by") AND fo_sales_has_word("updated_by"));
-- A named owner is staff of the same firm (FO-1a's trigger function), and a rule never moves firm.
CREATE TRIGGER "fo_assignment_rule_owner_in_firm" BEFORE INSERT OR UPDATE OF "owner_staff_id", "firm_id" ON "fo_assignment_rule" FOR EACH ROW EXECUTE FUNCTION fo_sales_owner_in_firm();
CREATE TRIGGER "fo_assignment_rule_firm_fixed" BEFORE UPDATE OF "firm_id" ON "fo_assignment_rule" FOR EACH ROW EXECUTE FUNCTION fo_sales_firm_fixed();
-- PF-12's walls: the database refuses another firm's rule even to a query that forgets its firm filter.
ALTER TABLE "fo_assignment_rule" ENABLE ROW LEVEL SECURITY, FORCE ROW LEVEL SECURITY;
CREATE POLICY "pf12_firm" ON "fo_assignment_rule" USING ("firm_id" = platform_session_firm()) WITH CHECK ("firm_id" = platform_session_firm());
CREATE TRIGGER "0_pf12_firm_first" BEFORE INSERT OR UPDATE ON "fo_assignment_rule" FOR EACH ROW EXECUTE FUNCTION platform_firm_first('firm_id');
